    const expressionsWithDefaultTheme = expressions
      ? expressions.map((stylesArg) => {
          return typeof stylesArg === 'function'
            ? ({ theme: themeInput, ...other }) => {
                return stylesArg({
                  theme: isEmpty(themeInput) ? defaultTheme : themeInput,
                  ...other,
